// All Star money flow: statements and paying the Heroes for the store owner, payment confirmation for the Heroes, the
// All Star credit notes tab and reconciliation on the DP World InSync portal, and in the admin All Star app the month's
// credit notes, closing a month (Store of the Month; quarter close with owner rebates and Store of the Quarter) and
// releasing a held credit note. Database: stravik_as_credit_notes, stravik_as_cn_lines, stravik_as_payouts,
// stravik_as_quarters, stravik_as_closes and their functions.
const fs = require("fs");
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [from, to] of pairs) {
    const n = s.split(from).length - 1;
    if (n !== 1) { console.error(`${file}: expected the text once, found it ${n} times: ${from.slice(0, 70)}`); process.exit(1); }
    s = s.replace(from, () => to);
  }
  fs.writeFileSync(file, s);
  console.log(file + ": updated");
}
